<?php
declare(strict_types=1);
use ImAuthenticator\Security;use ImAuthenticator\Web;
$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();$appId=(int)($_GET['id']??0);$app=$db->one('SELECT * FROM applications WHERE id=? AND deleted_at IS NULL',[$appId]);if(!$app){http_response_code(404);Web::page('Nie znaleziono','<div class="alert danger">Nie znaleziono aplikacji.</div>',$user);}if(!$appAdmins->canManage((int)$user['id'],$appId,'manage_admins')){http_response_code(403);Web::page('Brak dostępu','<div class="alert danger">Brak uprawnień do administratorów aplikacji.</div>',$user);}$message='';
if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);$action=(string)($_POST['action']??'');$target=(int)($_POST['user_id']??0);try{if($target<1)throw new RuntimeException('Wybierz użytkownika.');if($action==='add_owner'){$primary=$db->one('SELECT 1 FROM application_owners WHERE application_id=? AND is_primary=1',[$appId])?0:1;$db->execute('INSERT INTO application_owners(application_id,user_id,is_primary,created_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE is_primary=GREATEST(is_primary,VALUES(is_primary))',[$appId,$target,$primary,(int)$user['id']]);$audit->write('application.owner.assigned','success',(int)$user['id'],$target,$appId);}elseif($action==='set_primary'){$db->transaction(function()use($db,$appId,$target):void{$db->execute('UPDATE application_owners SET is_primary=0 WHERE application_id=?',[$appId]);$db->execute('UPDATE application_owners SET is_primary=1 WHERE application_id=? AND user_id=?',[$appId,$target]);});$audit->write('application.owner.primary_changed','success',(int)$user['id'],$target,$appId);}elseif($action==='remove_owner'){$count=$db->one('SELECT COUNT(*) AS c FROM application_owners WHERE application_id=?',[$appId]);if((int)($count['c']??0)<=1)throw new RuntimeException('Nie można usunąć ostatniego właściciela aplikacji.');$db->execute('DELETE FROM application_owners WHERE application_id=? AND user_id=?',[$appId,$target]);$audit->write('application.owner.removed','success',(int)$user['id'],$target,$appId);}elseif($action==='save_admin'){$allowed=['manage_users','manage_roles','manage_access','manage_config','manage_security','manage_scim','manage_admins'];$permissions=[];foreach($allowed as$p)if(isset($_POST['permissions'][$p]))$permissions[$p]=true;if($permissions===[])throw new RuntimeException('Wybierz co najmniej jedno uprawnienie.');$json=json_encode($permissions,JSON_THROW_ON_ERROR);$before=$db->one('SELECT permissions_json FROM application_admins WHERE application_id=? AND user_id=?',[$appId,$target]);$db->execute('INSERT INTO application_admins(application_id,user_id,permissions_json,created_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE permissions_json=VALUES(permissions_json),created_by=VALUES(created_by)',[$appId,$target,$json,(int)$user['id']]);$audit->write('application.delegated_admin.saved','success',(int)$user['id'],$target,$appId,null,['before'=>$before['permissions_json']??null,'after'=>$json]);}elseif($action==='remove_admin'){$db->execute('DELETE FROM application_admins WHERE application_id=? AND user_id=?',[$appId,$target]);$audit->write('application.delegated_admin.removed','success',(int)$user['id'],$target,$appId);}Web::redirect('/admin/applications/'.$appId.'/administrators');}catch(Throwable$e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}
$options='';foreach($db->all("SELECT id,name,email FROM users WHERE enabled=1 AND lifecycle_status='active' ORDER BY name,email")as$u)$options.='<option value="'.(int)$u['id'].'">'.Web::e($u['name'].' — '.$u['email']).'</option>';$owners='';foreach($db->all('SELECT ao.*,u.name,u.email FROM application_owners ao JOIN users u ON u.id=ao.user_id WHERE ao.application_id=? ORDER BY ao.is_primary DESC,u.name',[$appId])as$o)$owners.='<tr><td>'.Web::e($o['name']).'</td><td>'.Web::e($o['email']).'</td><td>'.((bool)$o['is_primary']?'Główny':'Właściciel').'</td><td><form class="inline" method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="user_id" value="'.(int)$o['user_id'].'"><button name="action" value="set_primary">Ustaw głównego</button><button class="danger" name="action" value="remove_owner">Usuń</button></form></td></tr>';if($owners==='')$owners='<tr><td colspan="4">Brak właściciela.</td></tr>';$admins='';foreach($db->all('SELECT aa.*,u.name,u.email FROM application_admins aa JOIN users u ON u.id=aa.user_id WHERE aa.application_id=? ORDER BY u.name',[$appId])as$a){$perms=array_keys(json_decode((string)$a['permissions_json'],true)?:[]);$admins.='<tr><td>'.Web::e($a['name']).'</td><td>'.Web::e($a['email']).'</td><td>'.Web::e(implode(', ',$perms)).'</td><td><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="user_id" value="'.(int)$a['user_id'].'"><button class="danger" name="action" value="remove_admin">Usuń delegację</button></form></td></tr>';}if($admins==='')$admins='<tr><td colspan="4">Brak delegowanych administratorów.</td></tr>';$checks='';foreach(['manage_users'=>'Użytkownicy','manage_roles'=>'Role aplikacyjne','manage_access'=>'Dostęp','manage_config'=>'Konfiguracja klienta','manage_security'=>'Conditional/OAuth Security','manage_scim'=>'SCIM','manage_admins'=>'Administratorzy aplikacji']as$key=>$label)$checks.='<label class="check"><input type="checkbox" name="permissions['.$key.']" value="1"> '.Web::e($label).'</label>';
$content='<div class="page-head"><div><h1>Właściciele i administratorzy — '.Web::e($app['name']).'</h1><p>Delegowany administrator nie otrzymuje globalnych praw administratora systemu.</p></div><a class="button" href="/admin/applications/'.$appId.'">Wróć</a></div>'.$message.'<section class="card"><h2>Właściciel aplikacji</h2><form method="post" class="toolbar"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><select name="user_id">'.$options.'</select><button name="action" value="add_owner">Dodaj właściciela</button></form><div class="table-wrap"><table><thead><tr><th>Osoba</th><th>E-mail</th><th>Typ</th><th>Akcje</th></tr></thead><tbody>'.$owners.'</tbody></table></div></section><section class="card"><h2>Delegowany administrator</h2><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Użytkownik<select name="user_id">'.$options.'</select></label><div class="checks">'.$checks.'</div><button class="primary" name="action" value="save_admin">Nadaj / zaktualizuj uprawnienia</button></form><div class="table-wrap"><table><thead><tr><th>Osoba</th><th>E-mail</th><th>Uprawnienia</th><th>Akcje</th></tr></thead><tbody>'.$admins.'</tbody></table></div></section>';Web::page('Administratorzy aplikacji',$content,$user);
